from fastapi import FastAPI, Body
from pydantic import BaseModel, ConfigDict
from fastapi.testclient import TestClient

app = FastAPI()

class MyClass:
    def __init__(self, name: str):
        self.name = name
    def __repr__(self):
        return f"MyClass(name={self.name})"

class Item(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    value: MyClass

@app.post("/item")
def create_item(item: Item):
    return {"value": item.value.name}

@app.post("/myclass")
def create_myclass(item: MyClass = Body(...)):
    return {"value": item.name}

client = TestClient(app)

def test_item():
    # This should work because Item is a BaseModel and has arbitrary_types_allowed=True
    # But wait, how do we send MyClass in JSON? We can't. 
    # Pydantic's arbitrary_types_allowed is for validation of the object, 
    # but it doesn't magically make a custom class JSON-serializable.
    pass

def test_myclass():
    # This uses Body(), so it should be treated as complex regardless of field_annotation_is_complex
    pass

if __name__ == "__main__":
    # Just to see if it runs
    print("Running reproduction...")
    # We need a way to trigger the bug.
    # The bug is likely when a type is used WITHOUT Body() but is intended to be complex.
    # But if it's not a BaseModel, FastAPI defaults to query param.
    pass

