import asyncio
import functools
from partial import partial # Wait, partial is from functools
from functools import partial
import inspect
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async"

def sync_func():
    return "sync"

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def async_wrapper(func):
    @functools.wraps(func)
    async def wrapped(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapped

def test_combinations():
    cases = [
        ("async_func", async_func, True),
        ("sync_func", sync_func, False),
        ("wrapped_async", wrapper(async_func), True),
        ("wrapped_sync", wrapper(sync_func), False),
        ("async_wrapped_async", async_wrapper(async_func), True),
        ("async_wrapped_sync", async_wrapper(sync_func), True),
        ("partial_async", partial(async_func), True),
        ("partial_sync", partial(sync_func), False),
        ("partial_wrapped_async", partial(wrapper(async_func)), True),
        ("partial_wrapped_sync", partial(wrapper(sync_func)), False),
        ("wrapped_partial_async", wrapper(partial(async_func)), True),
        ("wrapped_partial_sync", wrapper(partial(sync_func)), False),
        ("partial_async_wrapped_async", partial(async_wrapper(async_func)), True),
        ("partial_async_wrapped_sync", partial(async_wrapper(sync_func)), True),
    ]

    for name, func, expected in cases:
        dep = Dependant(call=func)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result}")
        assert result == expected, f"Failed {name}: expected {expected}, got {result}"

if __name__ == "__main__":
    try:
        test_combinations()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

