import asyncio
import inspect
from functools import wraps, partial
from fastapi.dependencies.models import Dependant

async def async_func():
    return "async"

def sync_func():
    return "sync"

def sync_wrapper(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

async def async_wrapper(func):
    @wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

def test_is_coroutine_callable():
    cases = [
        ("async_func", async_func, True),
        ("sync_func", sync_func, False),
        ("partial_async", partial(async_func), True),
        ("partial_sync", partial(sync_func), False),
        ("partial_partial_async", partial(partial(async_func)), True),
        ("sync_wrapped_sync", sync_wrapper(sync_func), False),
        ("sync_wrapped_async", sync_wrapper(async_func), True), # Wrapper is sync, but wrapped is async. Wait, if wrapper is sync, it returns a coroutine object if wrapped is async.
        ("async_wrapped_sync", async_wrapper(sync_func), True), # Wrapper is async, wrapped is sync.
        ("async_wrapped_async", async_wrapper(async_func), True),
        ("partial_sync_wrapped_async", partial(sync_wrapper(async_func)), True),
        ("partial_async_wrapped_sync", partial(async_wrapper(sync_func)), True),
    ]

    for name, call, expected in cases:
        dep = Dependant(call=call)
        result = dep.is_coroutine_callable
        print(f"{name}: expected {expected}, got {result}")
        assert result == expected, f"{name} failed"

if __name__ == "__main__":
    try:
        test_is_coroutine_callable()
        print("All tests passed!")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

