import functools
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature
import inspect

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def test_wrapped_forward_ref():
    # We simulate different globals by using a function to define the endpoint
    def create_endpoint():
        class LocalModel:
            pass

        def endpoint(param: "LocalModel"):
            return {"param": param}

        return wrapper(endpoint), LocalModel

    wrapped_endpoint, LocalModel = create_endpoint()

    print(f"Wrapped endpoint globals: {wrapped_endpoint.__globals__ is wrapper.__globals__}")

    try:
        sig = get_typed_signature(wrapped_endpoint)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_wrapped_forward_ref()

