from rich.highlighter import ReprHighlighter
from rich.text import Text

def test_url_tilde():
    highlighter = ReprHighlighter()
    text = Text("Visit http://example.com/~user")
    highlighter.highlight(text)

    # Check if the URL is highlighted
    # ReprHighlighter uses base_style = "repr."
    # The URL group is named "url", so it should have style "repr.url"

    found_url = False
    for span in text.spans:
        if span.style == "repr.url":
            if "~" in text.plain[span.start:span.end]:
                found_url = True
                break

    if found_url:
        print("SUCCESS: Tilde in URL is highlighted")
    else:
        print("FAILURE: Tilde in URL is NOT highlighted")
        print(f"Spans: {text.spans}")

if __name__ == "__main__":
    test_url_tilde()

